<template><div class="shell"><aside class="sidebar"><div class="side-brand">公益<span>咨询平台</span></div><div class="nav-title">工作空间</div>
  <router-link class="nav-link" to="/dashboard">▦ <span>工作台</span></router-link>
  <div class="nav-title">业务管理</div>
  <router-link v-for="item in menu" :key="item.key" class="nav-link" :to="'/workspace/'+item.key">{{item.icon}} <span>{{item.label}}</span></router-link>
</aside><main class="main"><header class="topbar"><div>欢迎回来，{{ user.nickname || user.username }}</div><div><el-tag size="small" type="info">{{roleName}}</el-tag><el-button type="text" style="margin-left:18px" @click="logout">退出登录</el-button></div></header>
  <section class="content"><h1 class="page-title">{{roleName}}工作台</h1><div class="muted">查看业务概况与近期动态</div>
    <div class="stat-grid"><div class="card" v-for="item in stats" :key="item.key"><div class="stat-label">{{item.label}}</div><div class="stat-value">{{summary[item.key] == null ? '—' : summary[item.key]}}</div></div></div>
    <div class="chart-grid"><div class="card"><div style="font-weight:600">预约状态分布</div><div id="statusChart" class="chart"></div></div><div class="card"><div style="font-weight:600">近12个月预约趋势</div><div id="monthChart" class="chart"></div></div></div>
    <h3 style="margin:28px 0 14px">快捷入口</h3><div class="workspace-grid"><router-link v-for="item in menu" :key="item.key" class="workspace-item" :to="'/workspace/'+item.key"><div style="font-size:22px;margin-bottom:12px">{{item.icon}}</div><b>{{item.label}}</b><p class="muted">进入{{item.label}}管理</p></router-link></div>
  </section></main></div></template>
<script>
import * as echarts from 'echarts'
import { dashboard, currentUser } from '../api/auth'
const menus={USER:[['professors','教授咨询','♧'],['appointments','我的预约','◷'],['resources','学习资源','▤'],['plans','学习计划','✓'],['community','学习社区','◎'],['questions','学习问答','?'],['messages','消息通知','✉']],PROFESSOR:[['appointments','预约管理','◷'],['schedule','日程管理','▦'],['consultations','咨询记录','▤'],['evaluations','学生评价','☆'],['messages','消息通知','✉']],ADMIN:[['users','用户管理','♙'],['professors','教授审核','♧'],['appointments','预约监管','◷'],['resources','资源管理','▤'],['articles','新闻公告','▣'],['community','社区管理','◎'],['questions','问答管理','?'],['evaluations','评价管理','☆'],['banners','轮播图管理','▧'],['roles','角色权限','◇'],['logs','操作日志','≡']]}
export default {data:()=>({user:{},summary:{},stats:[],statusRows:[],monthRows:[],menu:[]}),computed:{roleName(){return {USER:'普通用户',PROFESSOR:'教授',ADMIN:'管理员'}[this.user.role]||'用户'}},async mounted(){try{this.user=await currentUser();this.menu=(menus[this.user.role]||[]).map(x=>({key:x[0],label:x[1],icon:x[2]}));const d=await dashboard();this.summary=d.summary||{};this.statusRows=d.appointmentStatus||[];this.monthRows=d.monthlyAppointments||[];this.setStats();this.$nextTick(this.drawCharts)}catch(e){}},methods:{setStats(){const keys={USER:[['appointments','预约总数'],['pending','待确认预约'],['activePlans','进行中计划'],['unreadMessages','未读消息']],PROFESSOR:[['appointments','预约总数'],['pending','待处理预约'],['consultations','咨询记录'],['evaluations','收到评价']],ADMIN:[['users','普通用户数'],['pendingProfessors','待审核教授'],['appointments','平台预约数'],['pendingResources','待审核资源']]};this.stats=(keys[this.user.role]||[]).map(x=>({key:x[0],label:x[1]}))},drawCharts(){const s=echarts.init(document.getElementById('statusChart'));s.setOption({tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['42%','70%'],data:this.statusRows.map(x=>({name:x.name,value:x.value})),label:{formatter:'{b}：{c}'}}]});const m=echarts.init(document.getElementById('monthChart'));m.setOption({tooltip:{trigger:'axis'},grid:{left:38,right:20,top:25,bottom:35},xAxis:{type:'category',data:this.monthRows.map(x=>x.month)},yAxis:{type:'value',minInterval:1},series:[{type:'line',smooth:true,areaStyle:{opacity:.12},data:this.monthRows.map(x=>x.value)}]});window.addEventListener('resize',()=>{s.resize();m.resize()})},logout(){localStorage.clear();this.$router.replace('/login')}}}
</script>
